mapper.select:
SELECT a.account_id AS accountId, a.login_name AS loginName, a.email_masked AS emailMasked, TRUE AS active FROM t_user_account a JOIN t_access_tenant t ON t.tenant_type = 'INTERNAL' AND t.owner_ref_id = 1 AND t.owner_status = 'ACTIVE' AND t.security_status = 'ACTIVE' JOIN t_tenant_member m ON m.account_id = a.account_id AND m.tenant_id = t.tenant_id AND m.status = 'ACTIVE' WHERE a.realm = 'OPERATIONS' AND a.account_type = 'HUMAN' AND a.status = 'ACTIVE'
AND a.email_vault_token = #{emailToken}
AND (a.login_name LIKE CONCAT(#{fragment}, '%') ESCAPE '!' OR a.email_masked LIKE CONCAT('%', #{fragment}, '%') ESCAPE '!')
ORDER BY a.login_name IS NULL, a.login_name, a.email_masked, a.account_id LIMIT #{limit}
